function loungeCheckOwn(v,seat){return v===seat+1||v===seat+3;}
function loungeCheckCaptures(board,seat,from){
 const v=board[from];if(!loungeCheckOwn(v,seat))return [];
 const r=Math.floor(from/8),c=from%8,steps=v>=3?[-1,1]:[seat===0?-1:1],out=[];
 for(const dr of steps)for(const dc of [-1,1]){
  const rr=r+2*dr,cc=c+2*dc,mr=r+dr,mc=c+dc;
  if(rr<0||rr>7||cc<0||cc>7)continue;
  const mid=board[mr*8+mc];if(board[rr*8+cc]===0&&mid&&!loungeCheckOwn(mid,seat))out.push(rr*8+cc);
 }return out;
}
function loungeCheckMoves(board,seat,from,required){
 const v=board[from];if(!loungeCheckOwn(v,seat))return [];
 const caps=loungeCheckCaptures(board,seat,from);if(required)return caps;
 const r=Math.floor(from/8),c=from%8,steps=v>=3?[-1,1]:[seat===0?-1:1];
 for(const dr of steps)for(const dc of [-1,1]){
  const rr=r+dr,cc=c+dc;if(rr>=0&&rr<8&&cc>=0&&cc<8&&board[rr*8+cc]===0)caps.push(rr*8+cc);
 }return caps;
}
function loungeCheckHasMoves(board,seat){
 const required=board.some((v,i)=>loungeCheckOwn(v,seat)&&loungeCheckCaptures(board,seat,i).length);
 return board.some((v,i)=>loungeCheckOwn(v,seat)&&loungeCheckMoves(board,seat,i,required).length);
}
function loungeFleet(){
 const taken=new Set(),fleet=[];
 for(const length of [3,2,2]){
  let found=false;
  for(let tries=0;tries<500&&!found;tries++){
   const across=Math.random()<.5,x=Math.floor(Math.random()*(7-(across?length:1))),y=Math.floor(Math.random()*(7-(across?1:length)));
   const squares=Array.from({length},(_,i)=>(y+(across?0:i))*6+x+(across?i:0));
   if(squares.some(v=>taken.has(v)))continue;
   squares.forEach(v=>{taken.add(v);fleet.push(v)});found=true;
  }
  if(!found)return loungeFleet();
 }
 return fleet;
}

