function tttWinner(board) {
  const lines = [
    [0,1,2],[3,4,5],[6,7,8],
    [0,3,6],[1,4,7],[2,5,8],
    [0,4,8],[2,4,6],
  ];
  for (const [a,b,c] of lines) {
    if (board[a] && board[a] === board[b] && board[a] === board[c]) return board[a];
  }
  return board.every(Boolean) ? "draw" : null;
}

function c4Winner(board) {
  const rows = 6, cols = 7;
  const get = (r,c) => r >= 0 && r < rows && c >= 0 && c < cols ? board[r * cols + c] : null;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const v = get(r,c);
      if (!v) continue;
      for (const [dr,dc] of [[0,1],[1,0],[1,1],[1,-1]]) {
        let ok = true;
        for (let k = 1; k < 4; k++) {
          if (get(r + dr*k, c + dc*k) !== v) { ok = false; break; }
        }
        if (ok) return v;
      }
    }
  }
  return board.every(Boolean) ? "draw" : null;
}


// Moderation credentials are Cloudflare secrets. Never embed or send them in HTML.
const IDLE_WARN_MS=20*60*1000, IDLE_KICK_MS=25*60*1000, IDLE_CHECK_MS=60000;
